import requests

def check_endpoint(url, name):
    try:
        response = requests.get(url, timeout=10)
        print(f"{name}:\n  URL: {url}\n  Status: UP\n  HTTP Code: {response.status_code}\n  Response (truncated): {repr(response.text[:200])}\n")
    except Exception as e:
        print(f"{name}:\n  URL: {url}\n  Status: DOWN\n  Error: {e}\n")

# Check endpoints
check_endpoint('http://localhost:3003/checkConnectivity?variant=1', 'Local Service')
check_endpoint('https://httpstat.us/200', 'HTTPStat')
